vulnerable:
void copy_name(char *dst, const char *src) {
    strcpy(dst, src);
}

fixed:
void copy_name(char *dst, size_t n, const char *src) {
    if (n == 0) return;
    strncpy(dst, src, n - 1);
    dst[n - 1] = '\0';
}

vulnerable:
int get_item(int *arr, int len, int idx) {
    return arr[idx];
}

fixed:
int get_item(int *arr, int len, int idx) {
    if (idx < 0 || idx >= len) return -1;
    return arr[idx];
}

vulnerable:
void read_hdr(uint8_t *out, const uint8_t *pkt, size_t pkt_len) {
    size_t n = pkt[0];
    memcpy(out, pkt + 1, n);
}

fixed:
void read_hdr(uint8_t *out, size_t out_len, const uint8_t *pkt, size_t pkt_len) {
    size_t n = pkt[0];
    if (n > out_len || n + 1 > pkt_len) return;
    memcpy(out, pkt + 1, n);
}

vulnerable:
void log_msg(const char *user) {
    char buf[64];
    sprintf(buf, "user=%s", user);
    puts(buf);
}

fixed:
void log_msg(const char *user) {
    char buf[64];
    snprintf(buf, sizeof buf, "user=%s", user);
    puts(buf);
}

vulnerable:
void release(struct conn *c) {
    free(c->buf);
    if (c->err) log_err(c->buf);
}

fixed:
void release(struct conn *c) {
    if (c->err) log_err(c->buf);
    free(c->buf);
    c->buf = NULL;
}

vulnerable:
size_t total(size_t a, size_t b) {
    return a * b;
}
void *alloc_grid(size_t w, size_t h) {
    return malloc(total(w, h));
}

fixed:
void *alloc_grid(size_t w, size_t h) {
    if (h != 0 && w > SIZE_MAX / h) return NULL;
    return malloc(w * h);
}

vulnerable:
void append(char *dst, size_t cap, const char *s) {
    strcat(dst, s);
}

fixed:
void append(char *dst, size_t cap, const char *s) {
    size_t used = strlen(dst);
    if (used + strlen(s) + 1 > cap) return;
    memcpy(dst + used, s, strlen(s) + 1);
}

vulnerable:
int parse_len(const char *p) {
    int n = atoi(p);
    char *buf = malloc(n);
    return buf ? 0 : -1;
}

fixed:
int parse_len(const char *p) {
    long n = strtol(p, NULL, 10);
    if (n <= 0 || n > 4096) return -1;
    char *buf = malloc((size_t)n);
    return buf ? 0 : -1;
}
